const j=$input.first().json;
const hash=s=>{let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16).padStart(8,'0')+'-'+s.length;};
if(!Array.isArray(j.posts)||!j.posts.length) throw new Error('posts required');
if(!Array.isArray(j.channels)||!j.channels.length) throw new Error('channels with verified per-account quotas required');
const caps=new Map(j.channels.map(c=>[String(c.channel_id),Number(c.verified_daily_quota)]));
for(const [id,n] of caps) if(!Number.isInteger(n)||n<1) throw new Error('invalid verified quota for '+id);
const seen=new Set(),counts=new Map(),out=[]; for(const p of j.posts){const id=String(p.channel_id||'');if(!caps.has(id))throw new Error('unknown channel '+id);if(!p.character_id||!p.content_brief)throw new Error('character_id/content_brief required');const k=id+'|'+p.character_id+'|'+String(p.content_brief).trim().toLowerCase();if(seen.has(k))continue;seen.add(k);const n=(counts.get(id)||0)+1;if(n>caps.get(id))throw new Error('daily channel quota exceeded: '+id);counts.set(id,n);out.push({json:{queue_key:hash(k),channel_id:id,character_id:p.character_id,content_brief:p.content_brief,slot:n,media_status:'pending_configured_worker',schedule_status:'draft',approval_required:true,publish_enabled:false}})}
return out;
